import {ensurePdp} from './pdp.js';
import {ensureProPadel} from './pro-padel.js';
import {importReservation,deskAction} from './operations.js';
import {account,record,outstandingDebt,candidates} from './desk-domain.js';
import {uid,today,shiftDate,minutes,timeLabel,euro,received,outstanding,createSeed,addBooking} from './domain.js';
import {DemoPlaytomicAdapter} from './playtomic.js';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths={grid:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',calendar:'M4 5h16v16H4z M4 10h16 M8 3v4 M16 3v4',users:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2 M15 4a4 4 0 0 1 0 8 M22 21v-2a4 4 0 0 0-3-3 M13 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0',wallet:'M3 5h16v4 M3 5v15h18V9H6a3 3 0 0 1-3-4 M16 13h5v4h-5z',trophy:'M8 3h8v7a4 4 0 0 1-8 0z M8 5H4v3a4 4 0 0 0 4 4 M16 5h4v3a4 4 0 0 1-4 4 M12 14v7 M8 21h8',chart:'M4 3v18h17 M8 16v-5 M13 16V6 M18 16v-8',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8 M9 3h6l1 3 3 1 2 5-2 2-1 4-4 3-3-1-4-1-3-4 1-3-1-3 4-4z',link:'M10 13a5 5 0 0 0 7 0l3-3a5 5 0 0 0-7-7l-2 2 M14 11a5 5 0 0 0-7 0l-3 3a5 5 0 0 0 7 7l2-2',plus:'M12 5v14 M5 12h14',arrow:'M5 12h14 M14 7l5 5-5 5',left:'M14 6l-6 6 6 6',right:'M10 6l6 6-6 6',close:'M6 6l12 12 M18 6L6 18',search:'M21 21l-5-5 M18 10a7 7 0 1 1-14 0 7 7 0 0 1 14 0',bell:'M5 17h14l-2-3V9a5 5 0 0 0-10 0v5z M10 21h4',clock:'M12 8v5l3 2 M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',check:'M5 12l4 4L19 6',logout:'M9 3H4v18h5 M10 12h12 M17 7l5 5-5 5',court:'M4 3h16v18H4z M4 8h16 M4 16h16 M4 12h16 M12 3v5 M12 16v5',alert:'M12 3L2 21h20z M12 9v5 M12 17v1',download:'M12 3v12 M7 10l5 5 5-5 M4 17v4h16v-4',menu:'M4 6h16 M4 12h16 M4 18h16',refresh:'M20 7a8 8 0 1 0 0 10 M20 3v5h-5',shield:'M12 3l8 3v6c0 5-8 9-8 9s-8-4-8-9V6z M8 12l3 3 5-6'};
const icon=n=>`<svg aria-hidden="true" viewBox="0 0 24 24"><path d="${paths[n]||paths.grid}"/></svg>`;
const names={lessons:'Lezioni',overview:'Panoramica',agenda:'Agenda campi',matches:'Partite aperte',members:'Giocatori e soci',cash:'Cassa e pagamenti',events:'Tornei e attività',staff:'Personale e maestri',reports:'Statistiche',integration:'Playtomic',admin:'Amministrazione'};
const STORE='padel-club-os:v1';
let storageError=''; let state;
try { const saved=localStorage.getItem(STORE); state=saved?JSON.parse(saved):createSeed(); if(state.version!==1||!Array.isArray(state.clubs)||!state.clubs.length) throw Error(); } catch {state=createSeed();storageError='Archivio locale non disponibile o non valido. È stata aperta una nuova demo.';}
function normalizeCourts(data){
 ensurePdp(data);
 for(const c of data.clubs){
  c.courts.forEach((court,index)=>court.name='Campo '+(index+1));
  while(c.courts.length<6)c.courts.push({id:c.id+'-court-'+(c.courts.length+1),name:'Campo '+(c.courts.length+1),type:''});
 }
}
ensureProPadel(state);
normalizeCourts(state);
let serverRole=null;let revision=null, liveWhatsApp=false, pendingSave=Promise.resolve(), queued=0;
if(location.protocol.startsWith('http')){
 try{const r=await fetch('/api/desk');if(r.ok&&r.headers.get('content-type')?.includes('application/json')){const data=await r.json();serverRole=data.role;state=data.state;normalizeCourts(state);revision=data.revision;liveWhatsApp=data.live}}catch{}
}
async function refreshDesk(){
 if(revision===null||queued||document.querySelector('dialog[open]')||document.activeElement?.matches('input,select,textarea'))return;
 const r=await fetch('/api/desk');if(!r.ok)return;const data=await r.json();
 if(!queued&&data.revision>revision){state=data.state;revision=data.revision;render()}
}
setInterval(()=>refreshDesk().catch(()=>{}),5000);
let session=null;try{session=JSON.parse(sessionStorage.getItem('padel-demo-session'));}catch{}
if(session&&!state.clubs.some(c=>c.id===session.clubId))session=null;
if(session&&serverRole)session.role=serverRole;let page='overview',date=today(),view='grid',filter='',mobileOpen=false;
const club=()=>state.clubs.find(c=>c.id===(session?.clubId||state.clubs[0].id));
const bookings=()=>state.bookings.filter(b=>b.clubId===club().id&&b.status!=='cancelled');
const daily=()=>bookings().filter(b=>b.date===date);
const members=()=>state.members.filter(m=>m.clubId===club().id);
const moneyTotal=arr=>arr.reduce((s,b)=>s+received(b),0);
function persist(){if(revision!==null){const snapshot=structuredClone(state);queued++;
 pendingSave=pendingSave.then(async()=>{const r=await fetch('/api/desk',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({state:snapshot,revision})});if(!r.ok)throw Error('Salvataggio rifiutato. Ricarica prima di ripetere.');revision=(await r.json()).revision}).catch(e=>{toast(e.message);setTimeout(()=>location.reload(),1500);throw e}).finally(()=>queued--);return true;}try{localStorage.setItem(STORE,JSON.stringify(state));return true;}catch{toast('Memoria locale piena o non disponibile: esporta un backup prima di chiudere.');return false;}}
let toastTimer;function toast(message){$('#toast').textContent=message;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),4500);}
function contrast(hex){const v=hex.slice(1).match(/../g).map(x=>parseInt(x,16)/255).map(x=>x<=.04045?x/12.92:((x+.055)/1.055)**2.4);return .2126*v[0]+.7152*v[1]+.0722*v[2]>.35?'#172923':'#ffffff';}
function theme(c=club()){for(const key of ['primary','accent','canvas'])document.documentElement.style.setProperty('--'+key,c[key]);document.documentElement.style.setProperty('--on-primary',contrast(c.primary));document.documentElement.style.setProperty('--on-accent',contrast(c.accent));}
function mark(login=false){const c=club(),logo=login?(c.loginLogo||c.logo):c.logo;return `<span class="brandmark ${c.id==='pdp'?'pdp-logo':''}">${logo?`<img src="${esc(logo)}" alt="Logo ${esc(c.name)}">`:esc(c.initials)}</span>`;}
function brand(login=false){return `<div class="brand ${club().id==='pdp'?'pdp-brand':''}">${mark(login)}<div><b>${club().id==='pdp'?'PDP':'padel'}</b><small>GESTIONE CIRCOLO</small></div></div>`;}
function setSession(s){if(s&&serverRole)s.role=serverRole;session=s;try{s?sessionStorage.setItem('padel-demo-session',JSON.stringify(s)):sessionStorage.removeItem('padel-demo-session');}catch{}date=today();filter='';page='overview';render();}
function render(){theme();if(!session){renderLogin();return;}const c=club();document.title=`${names[page]} · ${c.name}`;const nav=[['overview','grid','Panoramica'],['lessons','users','Lezioni'],['matches','court','Partite aperte'],['members','users','Giocatori e soci'],['cash','wallet','Cassa e pagamenti'],['events','trophy','Tornei e attività'],['staff','users','Personale e maestri'],['reports','chart','Statistiche']];
$('#app').innerHTML=`<aside class="sidebar ${mobileOpen?'open':''}">${brand()}<div class="club-chip"><strong>${esc(c.name)}</strong><span>${esc(c.city)} · ${c.courts.length} campi</span></div><div class="nav-label">IL TUO CIRCOLO</div><nav class="nav" aria-label="Navigazione principale">${nav.map(([p,i,t])=>`<button data-page="${p}" class="${page===p?'active':''}" ${page===p?'aria-current="page"':''}>${icon(i)}${t}${p==='matches'?`<span class="tag-count">${bookings().filter(b=>b.kind==='match'&&b.players.length<4&&b.date>=today()).length}</span>`:''}</button>`).join('')}</nav><div class="nav-label">CONFIGURAZIONE</div><nav class="nav" aria-label="Configurazione"><button data-page="integration" class="${page==='integration'?'active':''}">${icon('link')}Playtomic <span class="tag-count">DEMO</span></button>${session.role==='owner'?`<button data-page="admin" class="${page==='admin'?'active':''}">${icon('settings')}Amministrazione</button>`:''}</nav><div class="sidebar-bottom"><div class="demo-badge"><b>${icon('shield')} Ambiente dimostrativo</b><p>Dati salvati su questo browser.<br>Nessuna connessione Playtomic reale.</p></div><div class="profile"><div class="avatar">${session.role==='owner'?'TU':'ST'}</div><div>${session.role==='owner'?'Il tuo pannello':'Staff del circolo'}<small>Ruolo demo · ${session.role==='owner'?'Proprietario':'Reception'}</small></div><button data-action="logout" title="Esci dalla demo" aria-label="Esci dalla demo">${icon('logout')}</button></div></div></aside><div class="shell"><header class="topbar"><button class="icon-btn mobile-menu" data-action="menu" aria-label="Apri o chiudi menu">${icon('menu')}</button><div class="breadcrumb">Circolo <span>/</span><strong>${page==='overview'?'Panoramica':names[page]}</strong></div><div class="top-actions"><button class="search" data-action="search">${icon('search')} Cerca giocatori o partite <kbd>⌘ K</kbd></button><span class="date-top">${new Intl.DateTimeFormat('it-IT',{day:'numeric',month:'long',year:'numeric',timeZone:'Europe/Rome'}).format(new Date())}</span><button class="icon-btn notify" data-action="alerts" aria-label="Apri avvisi">${icon('bell')}</button><div class="avatar" style="width:30px;height:30px;font-size:10px">${esc(c.initials)}</div></div></header><main id="main">${pageContent()}</main></div>`;
bind(); animatePage(); if(storageError){toast(storageError);storageError='';}}
function renderLogin(){const c=club();$('#app').innerHTML=`<div class="login"><section class="login-art">${brand(true)}<h1>Il tuo circolo.<br><span>Ogni giorno.</span></h1><p>CAMPI · SOCI · ATTIVITÀ</p><div class="court-art"></div></section><section class="login-form"><div class="login-box"><div class="eyebrow">BENVENUTO NEL CLUB</div><h2>Accedi al circolo</h2><p>Scegli il circolo e apri il gestionale.</p><form id="login-form"><label class="field"><span>Seleziona il circolo demo</span><select id="login-club">${state.clubs.map(c=>`<option value="${esc(c.id)}">${esc(c.name)}</option>`).join('')}</select></label><label class="field"><span>Esplora come</span><select name="role"><option value="owner">Proprietario · tutti i circoli e personalizzazione</option><option value="staff">Reception · operatività del circolo</option></select></label><button class="button" type="submit">Entra nella demo ${icon('arrow')}</button></form><div class="login-note">Anteprima senza password. I ruoli sono simulati e non costituiscono una protezione di accesso. Usa soltanto dati di prova.</div></div></section></div>`;$('#login-club').onchange=e=>{const target=state.clubs.find(c=>c.id===e.target.value);theme(target);const holder=$('.login-art .brandmark');holder.innerHTML=target.loginLogo||target.logo?`<img src="${esc(target.loginLogo||target.logo)}" alt="Logo ${esc(target.name)}">`:esc(target.initials);};$('#login-form').onsubmit=e=>{e.preventDefault();setSession({clubId:$('#login-club').value,role:new FormData(e.target).get('role')});};}
function head(description,action=true){return `<div class="page-head"><div><div class="eyebrow">${esc(club().name)} / Gestione circolo</div><h1>${names[page]}</h1><p>${description}</p></div>${action?`<button class="button" data-action="new-booking">${icon('plus')} Nuova prenotazione</button>`:''}</div>`;}
function stats(){const arr=daily().filter(b=>b.kind!=='block'),receivedTotal=moneyTotal(arr),due=arr.reduce((s,b)=>s+outstanding(b),0),hours=arr.reduce((s,b)=>s+b.duration/60,0),occupancy=Math.round(hours/(club().courts.length*16)*100),open=arr.filter(b=>b.kind==='match'&&b.players.length<4).length;return `<div class="stats"><article class="stat"><div class="stat-label">Prenotazioni del giorno ${icon('calendar')}</div><strong>${String(arr.length).padStart(2,'0')}</strong><small>${arr.reduce((s,b)=>s+b.players.length,0)} presenze previste</small></article><article class="stat"><div class="stat-label">Occupazione campi ${icon('court')}</div><strong>${occupancy}<span style="font-size:15px">%</span></strong><small>${hours.toLocaleString('it-IT')} ore su ${club().courts.length*16} disponibili</small></article><article class="stat highlight"><div class="stat-label">Quote incassate sulle partite ${icon('wallet')}</div><strong>${euro(receivedTotal)}</strong><small>${euro(due)} ancora da riscuotere</small></article><article class="stat"><div class="stat-label">Partite da completare ${icon('users')}</div><strong>${String(open).padStart(2,'0')}</strong><small>${arr.filter(b=>b.kind==='match').reduce((s,b)=>s+4-b.players.length,0)} posti ancora disponibili</small></article></div>`;}
function pageContent(){if(page==='lessons')return lessonsPage();if(page==='overview'||page==='agenda')return `${head(page==='overview'?'Uno sguardo al club. Ogni dettaglio sotto controllo.':'Disponibilità e prenotazioni, campo per campo.')}${stats()}<div class="workspace"><section class="panel">${agenda()}</section><aside class="rail">${attention()}${occupation()}<div class="panel pitch"><div class="eyebrow" style="color:inherit;opacity:.5;margin-bottom:13px">PARTITE APERTE</div><h2>Posti disponibili</h2><p>Trova i posti liberi e completa le partite del tuo circolo.</p><button class="button accent" data-page="matches">Vedi le partite ${icon('arrow')}</button><div class="court-art"></div></div></aside></div>${footer()}`;
if(page==='matches')return `${head('I posti liberi diventano nuove occasioni di gioco.')}${matchesPage()}`;
if(page==='members')return `${head('Anagrafiche, livello, pacchetti e scadenze in un unico elenco.',false)}<div class="panel"><div class="panel-head"><input class="filter-input" id="member-filter" aria-label="Cerca giocatore" placeholder="Cerca un giocatore…" value="${esc(filter)}"><button class="button" data-action="new-member">${icon('plus')} Aggiungi socio</button></div><div id="member-table">${memberTable()}</div></div>${footer()}`;
if(page==='cash')return shiftReport()+cashPage();if(page==='events')return eventsPage();if(page==='staff')return staffPage();if(page==='reports')return reportsPage();if(page==='integration')return integrationPage();if(page==='admin'&&session.role==='owner')return adminPage();return '';
}
function footer(){return `<div class="footer-note"><span>Gestione padel · Anteprima 0.1</span><span>Orari del circolo · Europe/Rome · Dati dimostrativi</span></div>`;}
function dateControl(){return `<div class="date-control"><button class="icon-btn" data-action="prev-day" aria-label="Giorno precedente">${icon('left')}</button><input type="date" id="agenda-date" aria-label="Data agenda" value="${date}"><button class="icon-btn" data-action="next-day" aria-label="Giorno successivo">${icon('right')}</button><button class="text-link" data-action="today">Oggi</button></div>`;}
function agenda(){return `<div class="panel-head"><h2>Agenda del giorno</h2><div class="legend"><span><i class="dot"></i>Completa</span><span><i class="dot orange"></i>Posti liberi</span><span><i class="dot blue"></i>Lezione</span></div></div><div class="toolbar">${dateControl()}<div class="segmented"><button data-view="grid" class="${view==='grid'?'selected':''}">Campi</button><button data-view="list" class="${view==='list'?'selected':''}">Elenco</button></div></div>${view==='list'?bookingTable(daily()):`<div class="agenda-scroll"><div class="agenda" style="--courts:${club().courts.length}"><div class="court-head">${icon('clock')}</div>${club().courts.map(c=>`<div class="court-head">${esc(c.name)}<small>${esc(c.type)}</small></div>`).join('')}<div class="time-column">${Array.from({length:32},(_,i)=>`<div class="time-label">${i%2===0?timeLabel(480+i*30):''}</div>`).join('')}</div>${club().courts.map(c=>`<div class="court-column">${Array.from({length:32},(_,i)=>`<button class="slot" style="top:${i*34}px" data-slot="${c.id}|${timeLabel(480+i*30)}" aria-label="Prenota ${esc(c.name)} alle ${timeLabel(480+i*30)}">+ Prenota</button>`).join('')}${daily().filter(b=>b.courtId===c.id).map(b=>bookingCard(b)).join('')}</div>`).join('')}</div></div>`}`;}
function bookingCard(b){return `<button class="booking ${b.kind==='lesson'?'lesson':b.kind==='block'?'block':b.players.length<4?'open':''}" style="top:${(minutes(b.start)-480)/30*34+3}px;height:${b.duration/30*34-6}px" data-booking="${b.id}" aria-label="${esc(b.title)}, ${b.start}, ${b.players.length} giocatori"><span class="booking-time">${b.start} – ${timeLabel(minutes(b.start)+b.duration)} ${b.source==='playtomic'?'↗':''}</span><strong>${b.eventId?'Torneo':b.kind==='block'?'Campo bloccato':b.technical?'Partita tecnica':b.kind==='lesson'?'Lezione':b.players.length===4?'Partita completa':`Cercasi ${4-b.players.length} giocator${b.players.length===3?'e':'i'}`}</strong><p>${esc(b.players[0]?.name||b.title)}</p><div class="booking-foot"><span class="mini-avatars">${b.players.map(p=>`<i>${esc(p.name.split(' ').map(n=>n[0]).slice(0,2).join(''))}</i>`).join('')}</span><span>${b.kind==='block'?'Blocco':`${b.players.length}/4 · ${euro(b.price)}`}</span></div></button>`;}
function bookingTable(arr){return arr.length?`<div class="table-wrap"><table><thead><tr><th>Partita</th><th>Data / Ora</th><th>Campo</th><th>Giocatori</th><th>Da riscuotere</th><th></th></tr></thead><tbody>${arr.sort((a,b)=>(a.date+a.start).localeCompare(b.date+b.start)).map(b=>`<tr><td><b>${esc(b.title)}</b><small>${b.source==='playtomic'?'Playtomic · demo':'Gestionale'} · ${b.kind==='lesson'?'Lezione':b.kind==='block'?'Blocco':'Partita'}</small></td><td>${esc(b.date)}<small>${b.start} – ${timeLabel(minutes(b.start)+b.duration)}</small></td><td>${esc(club().courts.find(c=>c.id===b.courtId)?.name||'—')}</td><td><span class="pill ${b.players.length<4?'warn':''}">${b.players.length}/4</span></td><td>${euro(outstanding(b))}</td><td><button class="text-link" data-booking="${b.id}">Apri ${icon('arrow')}</button></td></tr>`).join('')}</tbody></table></div>`:`<div class="empty">${icon('calendar')}Nessuna prenotazione per questa selezione.<br><button class="text-link" data-action="new-booking">Crea la prima prenotazione ${icon('plus')}</button></div>`;}
function attention(){const accepted=(state.searches||[]).filter(s=>s.clubId===club().id&&s.winner&&daily().some(b=>b.id===s.bookingId));const open=daily().filter(b=>b.kind==='match'&&b.players.length<4),due=daily().filter(b=>outstanding(b)>0),expired=members().filter(m=>m.certificate&&m.certificate<today());return `<section class="panel"><div class="panel-head"><h2>Da tenere d’occhio</h2><span class="live-label">Oggi</span></div><div class="attention">${accepted.map(s=>'<p class="pill">'+esc(members().find(m=>m.id===s.winner)?.name)+' ha accettato · inserire su Playtomic</p>').join('')}${[{icon:'users',title:`${open.length} partite da completare`,body:`${open.reduce((s,b)=>s+4-b.players.length,0)} giocatori mancanti nella giornata.`,target:'matches',link:'Trova i posti liberi'},{icon:'wallet',title:`${euro(due.reduce((s,b)=>s+outstanding(b),0))} da riscuotere`,body:`${due.length} prenotazioni con saldo da completare.`,target:'cash',link:'Apri la cassa'},{icon:'shield',title:`${expired.length} certificati scaduti`,body:expired.length?'Controlla le scadenze prima dell’attività.':'Le scadenze dei soci sono sotto controllo.',target:'members',link:'Controlla i soci'}].map(a=>`<div class="attention-item"><div class="alert-icon">${icon(a.icon)}</div><div><b>${a.title}</b><p>${a.body}</p><button class="text-link" data-page="${a.target}">${a.link} ${icon('arrow')}</button></div></div>`).join('')}</div></section>`;}
function occupation(){const value=Math.round(daily().filter(b=>b.kind!=='block').reduce((s,b)=>s+b.duration,0)/(club().courts.length*16*60)*100);return `<section class="panel occupation-panel"><div class="panel-head"><h2>Occupazione campi</h2></div><div class="occupation"><div class="ring" style="--value:${value}"><strong>${value}%</strong></div><p><b>${club().courts.length} campi, una sola visione.</b><br>Occupazione della giornata<br>Fascia 08:00 – 24:00</p></div></section>`;}
function matchesPage(){
 const arr=bookings().filter(b=>b.kind==='match'&&b.players.length<4&&b.date>=date).sort((a,b)=>(a.date+a.start).localeCompare(b.date+b.start));
 return headlessMatches(arr);
}
function headlessMatches(arr){
 return '<div class="toolbar" style="padding-left:0">'+dateControl()+'<span class="section-note">Dalla data selezionata</span></div>'+
 (arr.length?'<div class="cards">'+arr.map(b=>{
 const missing=4-b.players.length,court=club().courts.find(c=>c.id===b.courtId);
 return '<article class="panel event-card open-match"><div class="match-top"><span>'+esc(new Date(b.date+'T12:00:00').toLocaleDateString('it-IT',{weekday:'long',day:'numeric',month:'long'}))+'</span><span class="match-vacancy">'+missing+' '+(missing===1?'posto libero':'posti liberi')+'</span></div><div class="match-time">'+esc(b.start)+'<span>– '+timeLabel(minutes(b.start)+b.duration)+'</span></div><div class="match-facts"><div><small>Livello di gioco</small><strong>'+esc(b.level||'Tutti i livelli')+'</strong></div><div><small>Campo</small><strong>'+esc(court?.name||'Da assegnare')+'</strong></div></div><div class="match-roster">'+Array.from({length:4},(_,i)=>'<span class="'+(b.players[i]?'filled':'vacant')+'">'+(b.players[i]?esc(b.players[i].name):'Posto libero')+'</span>').join('')+'</div><div class="match-actions"><button class="button" data-booking="'+b.id+'">Apri partita</button><button class="button secondary" data-sub="'+b.id+'">Trova sostituto</button></div></article>';
 }).join('')+'</div>':'<div class="panel empty">'+icon('check')+'Nessuna partita da completare.</div>')+footer();
}
function memberTable(){const arr=members().filter(m=>(m.name+' '+m.phone).toLowerCase().includes(filter.toLowerCase()));return arr.length?`<div class="table-wrap"><table><thead><tr><th>Giocatore</th><th>Livello</th><th>Certificato</th><th>Pacchetto</th><th></th></tr></thead><tbody>${arr.map(m=>`<tr><td><b>${esc(m.name)}</b><small>${esc(m.phone||'Telefono non inserito')}</small></td><td><span class="pill gray">${esc(m.level)}</span></td><td>${m.certificate?`<span class="pill ${m.certificate<today()?'warn':''}">${m.certificate<today()?'Scaduto · ':''}${esc(m.certificate)}</span>`:'Da inserire'}</td><td>${esc(m.package||'Nessuno')}<small>${m.credits||0} ingressi residui</small></td><td><button class="text-link" data-wallet="${m.id}">Conto e preferenze</button> · <button class="text-link" data-member="${m.id}">Modifica ${icon('arrow')}</button></td></tr>`).join('')}</tbody></table></div>`:`<div class="empty">Nessun giocatore trovato.</div>`;}
function cashPage(){const arr=daily().filter(b=>b.kind!=='block'),expenses=state.expenses.filter(e=>e.clubId===club().id&&e.date===date),total=moneyTotal(arr),spending=expenses.reduce((s,e)=>s+e.amount,0);return `${head('Ogni quota al suo posto. Via internet, al circolo o ancora da saldare.',false)}<div class="toolbar" style="padding:0 0 20px">${dateControl()}<div class="actions"><button class="button secondary" data-action="export-cash">${icon('download')} Esporta CSV</button><button class="button" data-action="new-expense">${icon('plus')} Registra spesa</button></div></div><div class="stats"><div class="stat highlight"><div class="stat-label">Quote incassate</div><strong>${euro(total)}</strong><small>Sulle prenotazioni della data selezionata</small></div><div class="stat"><div class="stat-label">Da riscuotere</div><strong>${euro(arr.reduce((s,b)=>s+outstanding(b),0))}</strong><small>Incluse quote non ancora assegnate</small></div><div class="stat"><div class="stat-label">Spese registrate</div><strong>${euro(spending)}</strong><small>${expenses.length} movimenti</small></div><div class="stat"><div class="stat-label">Quote meno spese</div><strong>${euro(total-spending)}</strong><small>Riepilogo operativo, non fiscale</small></div></div><div class="panel"><div class="panel-head"><h2>Pagamenti per giocatore</h2></div>${arr.length?`<div class="table-wrap"><table><thead><tr><th>Giocatore</th><th>Prenotazione</th><th>Quota</th><th>Metodo</th><th>Stato</th><th></th></tr></thead><tbody>${arr.flatMap(b=>b.players.map((p,i)=>`<tr><td>${esc(p.name)}${debtBadge(b,p)}</td><td>${b.start} · ${esc(club().courts.find(c=>c.id===b.courtId)?.name)}</td><td>${euro(p.amount)}</td><td>${p.method==='online'?'Via internet':'Al circolo'}</td><td><span class="pill ${p.paid?'':'warn'}">${p.paid?'Pagato':'Da pagare'}</span></td><td><button class="text-link" data-payment="${b.id}|${i}">${p.paid?'Dettaglio':'Registra quota'} ${icon('arrow')}</button></td></tr>`)).join('')}</tbody></table></div>`:'<div class="empty">Nessun pagamento per questa giornata.</div>'}</div><div class="panel" style="margin-top:20px"><div class="panel-head"><h2>Spese della giornata</h2></div>${expenses.length?`<div class="table-wrap"><table><thead><tr><th>Descrizione</th><th>Importo</th></tr></thead><tbody>${expenses.map(e=>`<tr><td>${esc(e.description)}</td><td>${euro(e.amount)}</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">Nessuna spesa registrata.</div>'}</div>${footer()}`;}
function eventsPage(){const arr=state.events.filter(e=>e.clubId===club().id);return `${head('Americani, tornei sociali e appuntamenti che fanno vivere il club.',false)}<div class="actions" style="margin-bottom:20px"><button class="button" data-action="new-event">${icon('plus')} Nuova attività</button></div><div class="notice">Seleziona i campi durante la creazione per riservarli automaticamente in agenda.</div>${arr.length?`<div class="cards">${arr.map(e=>`<article class="panel event-card"><div class="event-date">${esc(e.date.slice(8))} / ${esc(e.date.slice(5,7))}</div><h2>${esc(e.title)}</h2><p>${esc(e.date)} alle ${esc(e.time)}<br>${e.participants.length}/${e.capacity} iscritti · ${euro(e.fee)} a persona</p><div class="progress"><i style="width:${e.participants.length/e.capacity*100}%"></i></div><button class="button secondary" data-event="${e.id}">Gestisci iscrizioni ${icon('arrow')}</button></article>`).join('')}</div>`:'<div class="panel empty">Nessuna attività. Crea il primo appuntamento del circolo.</div>'}${footer()}`;}
function staffPage(){const arr=state.staff.filter(s=>s.clubId===club().id);return `${head('Le persone che fanno funzionare il tuo circolo.',false)}<div class="actions" style="margin-bottom:20px"><button class="button" data-action="new-staff">${icon('plus')} Aggiungi al personale</button></div><div class="notice">Rubrica del personale in modalità demo. Gli account di accesso e i permessi reali saranno gestiti dal servizio di autenticazione.</div><div class="panel">${arr.length?`<div class="table-wrap"><table><thead><tr><th>Nome</th><th>Ruolo</th><th>Telefono</th><th></th></tr></thead><tbody>${arr.map(s=>`<tr><td>${esc(s.name)}</td><td>${esc(s.role)}</td><td>${esc(s.phone)}</td><td><button class="text-link" data-staff="${s.id}">Modifica ${icon('arrow')}</button></td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">Il personale è ancora vuoto.</div>'}</div>${footer()}`;}
function reportsPage(){const days=Array.from({length:7},(_,i)=>shiftDate(date,i-6)),values=days.map(d=>({date:d,arr:bookings().filter(b=>b.date===d&&b.kind!=='block')})),max=Math.max(...values.map(v=>v.arr.length),1);return `${head('Dati concreti per capire come si muove il circolo.',false)}<div class="toolbar" style="padding-left:0">${dateControl()}<span class="section-note">Riepilogo sui 7 giorni fino alla data selezionata</span></div>${stats()}<div class="grid-two"><section class="panel panel-pad"><h2>Prenotazioni · ultimi 7 giorni</h2><div class="bar-chart">${values.map(v=>`<div><b>${v.arr.length}</b><i style="height:${v.arr.length/max*130}px"></i><span>${v.date.slice(8)}/${v.date.slice(5,7)}</span></div>`).join('')}</div></section><section class="panel panel-pad"><h2>Utilizzo per campo · 7 giorni</h2>${club().courts.map(c=>{const hours=values.flatMap(v=>v.arr).filter(b=>b.courtId===c.id).reduce((s,b)=>s+b.duration/60,0);return `<div style="margin-top:20px"><div class="split"><span style="font-size:11px">${esc(c.name)}</span><span class="section-note">${hours.toLocaleString('it-IT')} h / 112 h</span></div><div class="progress"><i style="width:${hours/112*100}%"></i></div></div>`;}).join('')}</section></div>${footer()}`;}
function integrationPage(){return head('Calendario sorgente in sola lettura.',false)+'<section class="panel panel-pad"><h2>Importazione prenotazioni</h2><p>Leggi le prenotazioni simulate del giorno. I pagamenti e la ricerca dei sostituti si gestiscono al desk.</p><label class="field"><span>Data</span><input type="date" id="integration-date" value="'+date+'"></label><button class="button" data-action="import-demo">Importa prenotazioni demo</button></section>'+footer();}
function adminPage(){const c=club();return `${head('Personalizza i circoli e i campi.',false)}<div class="notice">Pannello proprietario dimostrativo. Le personalizzazioni si applicano a login, pannello e componenti del circolo selezionato. I ruoli demo non proteggono i dati: per l’uso commerciale servono autenticazione e isolamento sul server.</div><div class="panel panel-pad" style="margin-bottom:20px"><div class="split"><label class="field" style="margin:0;flex:1;max-width:360px"><span>Circolo da amministrare</span><select id="admin-club">${state.clubs.map(x=>`<option value="${esc(x.id)}" ${x.id===c.id?'selected':''}>${esc(x.name)}</option>`).join('')}</select></label><button class="button secondary" data-action="new-club">${icon('plus')} Nuovo circolo</button></div></div><div class="settings-grid"><section class="panel panel-pad"><h2 style="margin-bottom:22px">Identità e colori</h2><form id="brand-form"><div class="form-grid">${field('Nome circolo','name',c.name,'text',true)}${field('Città','city',c.city)}${field('Sigla','initials',c.initials)}<label class="field"><span>Colore principale</span><input type="color" name="primary" value="${c.primary}"></label><label class="field"><span>Colore accento</span><input type="color" name="accent" value="${c.accent}"></label><label class="field full"><span>Sfondo del gestionale</span><input type="color" name="canvas" value="${c.canvas}"></label><label class="field"><span>Logo pannello</span><input type="file" name="logo" accept="image/png,image/jpeg,image/webp"><small>PNG, JPG o WebP · massimo 500 KB</small></label><label class="field"><span>Logo login</span><input type="file" name="loginLogo" accept="image/png,image/jpeg,image/webp"><small>Se assente, usa il logo pannello.</small></label></div><label class="check"><input type="checkbox" name="clearLogos">Rimuovi entrambi i loghi e usa la sigla</label><p class="form-error" id="brand-error" role="alert"></p><button class="button" type="submit">${icon('check')} Salva personalizzazione</button></form></section><div><div class="brand-preview">${brand()}<h3>${esc(c.name)}</h3><p>Colori e identità del circolo</p><span class="button">Apri agenda ${icon('arrow')}</span></div><div class="panel panel-pad" style="margin-top:20px"><h2>Campi del circolo</h2>${c.courts.map(x=>`<div class="split" style="border-bottom:1px solid var(--line);padding:13px 0"><div style="font-size:11px"><b>${esc(x.name)}</b><small style="display:block;color:var(--muted);margin-top:5px">${esc(x.type)}${c.id==='pro-padel'&&Number.isFinite(x.price)?' · '+euro(x.price/4)+' a persona':''}</small></div><button class="text-link" data-court="${x.id}">Modifica</button></div>`).join('')}<button class="text-link" data-action="new-court">${icon('plus')} Aggiungi campo</button></div><div class="panel panel-pad" style="margin-top:20px"><h2>Copia dei dati</h2><p class="section-note" style="margin:12px 0">Esporta i dati di tutti i circoli da questo browser. Il file contiene solo i dati inseriti nella demo.</p><button class="button secondary" data-action="backup">${icon('download')} Scarica dati</button></div></div></div>${footer()}`;}
function field(label,name,value='',type='text',full=false){return `<label class="field ${full?'full':''}"><span>${label}</span><input type="${type}" name="${name}" value="${esc(value)}" ${['name','title','description'].includes(name)?'required':''} ${type==='number'?'min="0" step="0.01"':''} ${type==='text'?'maxlength="160"':''}></label>`;}
function showModal(title,body){$('#modal').innerHTML=`<div class="modal-head"><h2 id="modal-title">${title}</h2><button class="icon-btn" data-close aria-label="Chiudi finestra">${icon('close')}</button></div><div class="modal-body">${body}</div>`;$('#modal').showModal();$('#modal [data-close]').onclick=()=>$('#modal').close();$('#modal').onclick=e=>{if(e.target===$('#modal')){const r=$('#modal').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)$('#modal').close();}};}
function errorForm(form,error){form.querySelector('.form-error').textContent=error.message;}
function formModal(title,contents,onSave){showModal(title,`<form id="generic-form">${contents}<p class="form-error" role="alert"></p><div class="modal-foot"><button type="submit" class="button">${icon('check')} Salva</button></div></form>`);$('#generic-form').onsubmit=async e=>{e.preventDefault();try{await onSave(new FormData(e.target));persist();$('#modal').close();render();toast('Salvato nella demo.');}catch(error){errorForm(e.target,error);}};}
function openBooking(id){const b=bookings().find(b=>b.id===id);if(!b)return;showModal(esc(b.title),`<div class="split"><span class="pill ${b.players.length<4?'warn':''}">${b.kind==='block'?'Campo bloccato':`${b.players.length}/4 giocatori`}</span><span class="pill gray">${esc(b.sync)}</span></div><div class="detail-list"><div><small>Quando</small>${esc(b.date)} · ${b.start} – ${timeLabel(minutes(b.start)+b.duration)}</div><div><small>Campo</small>${esc(club().courts.find(c=>c.id===b.courtId)?.name)}</div><div><small>Prezzo totale</small>${euro(b.price)}</div><div><small>Da riscuotere</small>${euro(outstanding(b))}</div></div>${b.players.length?`<table><thead><tr><th>Giocatore</th><th>Quota</th><th>Pagamento</th></tr></thead><tbody>${b.players.map(p=>`<tr><td>${esc(p.name)}${debtBadge(b,p)}</td><td><button class="text-link" data-quota="${b.id}|${b.players.indexOf(p)}">${euro(p.amount)} ↗</button></td><td>${p.paid?'Pagato':'Da pagare'}<small>${p.method==='online'?'Via internet':'Al circolo'}</small></td></tr>`).join('')}</tbody></table>`:'<p class="section-note">Nessun giocatore inserito.</p>'}${b.notes?`<p class="section-note" style="margin-top:18px">${esc(b.notes)}</p>`:''}<div class="modal-foot"><button class="button danger" id="cancel-booking">Annulla prenotazione</button><button class="button" id="edit-booking">Modifica / aggiungi giocatori ${icon('arrow')}</button></div>`);$$('[data-quota]').forEach(btn=>btn.onclick=()=>{$('#modal').close();deskPayment(btn.dataset.quota);});$('#edit-booking').onclick=()=>{if(b.teacherId){toast('Per cambiare maestro, durata o ripartizione annulla la lezione e ricreala.');return;}$('#modal').close();bookingForm(b);};$('#cancel-booking').onclick=()=>{showModal('Annullare la prenotazione?',`<p class="section-note">Il campo tornerà disponibile. La prenotazione rimane nello storico demo.</p><div class="modal-foot"><button class="button secondary" id="back-booking">Torna alla partita</button><button class="button danger" id="confirm-cancel">Conferma annullamento</button></div>`);$('#back-booking').onclick=()=>{$('#modal').close();openBooking(id);};$('#confirm-cancel').onclick=()=>{b.status='cancelled';persist();$('#modal').close();render();toast('Prenotazione annullata nella demo.');};};}
function bookingForm(existing=null,slot=null){const c=club(),b=existing||{id:uid(),clubId:c.id,courtId:slot?.[0]||c.courts[0]?.id,date,start:slot?.[1]||'18:00',duration:90,kind:'match',title:'Partita amichevole',price:c.courts.find(x=>x.id===(slot?.[0]||c.courts[0]?.id))?.price??60,level:'3.0 – 4.0',notes:'',source:'club',sync:'local',externalId:null,status:'confirmed',players:[]};const options=(arr,value)=>arr.map(([v,t])=>`<option value="${v}" ${String(v)===String(value)?'selected':''}>${t}</option>`).join('');showModal(existing?'Modifica prenotazione':'Nuova prenotazione',`<form id="booking-form"><div class="form-grid">${field('Titolo','title',b.title,'text',true)}<label class="field"><span>Campo</span><select name="courtId">${c.courts.map(x=>`<option value="${esc(x.id)}" ${x.id===b.courtId?'selected':''}>${esc(x.name)}</option>`).join('')}</select></label>${field('Data','date',b.date,'date')}${field('Inizio','start',b.start,'time')}<label class="field"><span>Durata</span><select name="duration">${options([[60,'60 minuti'],[90,'90 minuti'],[120,'120 minuti']],b.duration)}</select></label><label class="field"><span>Tipo</span><select name="kind">${options([['match','Partita'],['lesson','Lezione'],['block','Blocco / manutenzione']],b.kind)}</select></label>${field('Prezzo totale €','price',b.price,'number')}${field('Livello','level',b.level)}<label class="field"><span>Note</span><input name="notes" maxlength="500" value="${esc(b.notes)}"></label></div><div class="split"><h2>Giocatori e quote</h2><span class="section-note">Lascia vuoti i posti liberi</span></div><div class="player-head"><span>Nome giocatore</span><span>Quota €</span><span>Metodo</span><span>Pagato</span></div><datalist id="member-names">${members().map(m=>`<option value="${esc(m.name)}"></option>`).join('')}</datalist>${Array.from({length:4},(_,i)=>{const p=b.players[i]||{name:'',amount:b.price/4,method:'club',paid:false};return `<div class="player-row"><input name="player${i}" list="member-names" placeholder="Posto libero" aria-label="Giocatore ${i+1}" maxlength="160" value="${esc(p.name)}"><input name="amount${i}" type="number" min="0" step="0.01" value="${p.amount}" aria-label="Quota giocatore ${i+1}"><select name="method${i}" aria-label="Metodo giocatore ${i+1}">${options([['club','Al circolo'],['online','Via internet']],p.method)}</select><input name="paid${i}" type="checkbox" ${p.paid?'checked':''} aria-label="Pagato giocatore ${i+1}"></div>`;}).join('')}<p class="form-error" role="alert"></p><div class="modal-foot"><button type="submit" class="button">${icon('check')} Salva prenotazione</button></div></form>`);if(!existing&&['pdp','pro-padel'].includes(c.id))$('#booking-form [name="courtId"]').onchange=e=>{const price=c.courts.find(x=>x.id===e.target.value)?.price;$('#booking-form [name="price"]').value=price;for(let i=0;i<4;i++)$('#booking-form [name="amount'+i+'"]').value=price/4;};$('#booking-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);try{const candidate={...b,courtId:f.get('courtId'),date:f.get('date'),start:f.get('start'),duration:Number(f.get('duration')),kind:f.get('kind'),title:f.get('title').trim(),price:Number(f.get('price')),level:f.get('level'),notes:f.get('notes'),players:Array.from({length:4},(_,i)=>({name:f.get('player'+i).trim(),amount:Number(f.get('amount'+i)),method:f.get('method'+i),paid:f.has('paid'+i)})).filter(p=>p.name)};if(candidate.kind==='block'){candidate.players=[];candidate.price=0;}if(!candidate.title)throw Error('Inserisci un titolo.');addBooking(state,candidate);persist();$('#modal').close();render();toast('Prenotazione salvata.');}catch(error){errorForm(e.target,error);}};}
function memberForm(id){const m=members().find(m=>m.id===id)||{id:uid(),clubId:club().id,name:'',phone:'',level:'3.0',certificate:'',package:'Nessuno',credits:0,notes:''};formModal(id?'Modifica socio':'Nuovo socio',`<div class="form-grid">${field('Nome e cognome','name',m.name,'text',true)}${field('Telefono','phone',m.phone,'tel')}${field('Livello','level',m.level)}${field('Scadenza certificato','certificate',m.certificate,'date')}${field('Pacchetto','package',m.package)}${field('Ingressi residui','credits',m.credits,'number')}<label class="field full"><span>Note</span><textarea name="notes" maxlength="1000">${esc(m.notes)}</textarea></label></div>`,f=>{const item={...m,...Object.fromEntries(f),name:f.get('name').trim(),credits:Number(f.get('credits'))};if(!item.name||!Number.isInteger(item.credits)||item.credits<0)throw Error('Inserisci nome e un numero intero di ingressi valido.');const i=state.members.findIndex(x=>x.id===m.id);i<0?state.members.push(item):state.members[i]=item;});}
function staffForm(id){const s=state.staff.find(x=>x.id===id&&x.clubId===club().id)||{id:uid(),clubId:club().id,name:'',role:'Maestro',phone:''};formModal(id?'Modifica membro del personale':'Aggiungi al personale',`${field('Nome e cognome','name',s.name)}<label class="field"><span>Ruolo</span><select name="role">${['Maestro','Reception','Responsabile','Manutenzione'].map(r=>`<option ${s.role===r?'selected':''}>${r}</option>`).join('')}</select></label>${field('Telefono','phone',s.phone,'tel')}`,f=>{const item={...s,...Object.fromEntries(f),name:f.get('name').trim()};if(!item.name)throw Error('Inserisci il nome.');const i=state.staff.findIndex(x=>x.id===s.id);i<0?state.staff.push(item):state.staff[i]=item;});}
function oldEventForm(){formModal('Nuova attività',`${field('Nome attività','title','')}${field('Data','date',date,'date')}${field('Orario','time','19:00','time')}${field('Numero massimo iscritti','capacity',16,'number')}${field('Quota individuale €','fee',25,'number')}`,f=>{const e={id:uid(),clubId:club().id,...Object.fromEntries(f),capacity:Number(f.get('capacity')),fee:Number(f.get('fee')),participants:[]};if(!e.title.trim()||!e.date||!e.time||!Number.isInteger(e.capacity)||e.capacity<1||e.fee<0)throw Error('Controlla titolo, data, orario, quota e capienza.');state.events.push(e);});}
function oldEventDetail(id){const e=state.events.find(x=>x.id===id&&x.clubId===club().id);if(!e)return;showModal(esc(e.title),`<p class="section-note">${esc(e.date)} · ${esc(e.time)} · ${e.participants.length}/${e.capacity} iscritti</p><div style="margin:18px 0">${e.participants.map((p,i)=>`<div class="split" style="padding:10px 0;border-bottom:1px solid var(--line);font-size:12px"><span>${esc(p)}</span><button class="text-link" data-remove-participant="${i}">Rimuovi</button></div>`).join('')||'<p class="section-note">Nessun iscritto.</p>'}</div><form id="participant-form"><label class="field"><span>Nome partecipante</span><input name="name" required maxlength="160" placeholder="Nome e cognome"></label><p class="form-error" role="alert"></p><button class="button" ${e.participants.length>=e.capacity?'disabled':''}>${icon('plus')} Aggiungi iscritto</button></form>`);$$('[data-remove-participant]').forEach(btn=>btn.onclick=()=>{e.participants.splice(Number(btn.dataset.removeParticipant),1);persist();$('#modal').close();render();eventDetail(id);});$('#participant-form').onsubmit=ev=>{ev.preventDefault();const name=new FormData(ev.target).get('name').trim();try{if(!name||e.participants.length>=e.capacity)throw Error('Nome mancante o attività al completo.');if(e.participants.some(p=>p.toLowerCase()===name.toLowerCase()))throw Error('Partecipante già iscritto.');e.participants.push(name);persist();$('#modal').close();render();eventDetail(id);}catch(error){errorForm(ev.target,error);}};}
