function courtForm(id){if(session.role!=='owner')return;const c=club(),court=c.courts.find(x=>x.id===id)||{id:uid(),name:'',type:'Panoramico · Coperto'};formModal(id?'Modifica campo':'Nuovo campo',`${field('Nome campo','name',court.name)}${field('Tipologia','type',court.type)}`,f=>{if(!f.get('name').trim())throw Error('Inserisci il nome del campo.');const item={...court,...Object.fromEntries(f)};const i=c.courts.findIndex(x=>x.id===court.id);i<0?c.courts.push(item):c.courts[i]=item;});}
