async function readLogo(file){if(!file?.size)return null;if(file.size>500*1024||!['image/png','image/jpeg','image/webp'].includes(file.type))throw Error('Il logo deve essere PNG, JPG o WebP e non superare 500 KB.');const result=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=()=>reject(Error('Impossibile leggere il logo.'));r.readAsDataURL(file);});await new Promise((resolve,reject)=>{const img=new Image();img.onload=resolve;img.onerror=()=>reject(Error('Immagine non valida.'));img.src=result;});return result;}
function exportFile(name,content,type){const url=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function csvCell(value){let v=String(value??'');if(/^[=+@\-\t\r]/.test(v))v="'"+v;return '"'+v.replace(/"/g,'""')+'"';}
function exportCash(){const rows=[['Data','Ora','Campo','Giocatore','Quota','Metodo','Pagato'],...daily().filter(b=>b.kind!=='block').flatMap(b=>b.players.map(p=>[b.date,b.start,club().courts.find(c=>c.id===b.courtId)?.name,p.name,p.amount,p.method==='online'?'Via internet':'Circolo',p.paid?'Sì':'No']))];exportFile(`pagamenti-${club().id}-${date}.csv`,'\ufeff'+rows.map(row=>row.map(csvCell).join(';')).join('\r\n'),'text/csv;charset=utf-8');toast('CSV esportato.');}
