function legacyPaymentModal(value){const [id,i]=value.split('|'),b=bookings().find(b=>b.id===id),p=b?.players[Number(i)];if(!p)return;formModal(p.paid?'Rettifica pagamento':'Registra pagamento',`<p class="section-note" style="margin-bottom:18px">${esc(p.name)} · ${euro(p.amount)} · ${esc(b.date)} ${b.start}</p><label class="field"><span>Metodo di pagamento</span><select name="method"><option value="club" ${p.method==='club'?'selected':''}>Al circolo</option><option value="online" ${p.method==='online'?'selected':''}>Via internet</option></select></label><label class="check"><input type="checkbox" name="paid" ${p.paid?'':'checked'}>Quota pagata</label><p class="section-note">Registrazione manuale nella demo. Nessun addebito e nessun aggiornamento ai pagamenti Playtomic.</p>`,f=>{p.paid=f.has('paid');p.method=f.get('method');});}
