function bind(){$$('[data-page]').forEach(b=>b.onclick=()=>{page=b.dataset.page;filter='';mobileOpen=false;render();});$$('[data-booking]').forEach(b=>b.onclick=()=>openBooking(b.dataset.booking));$$('[data-slot]').forEach(b=>b.onclick=()=>bookingForm(null,b.dataset.slot.split('|')));$$('[data-member]').forEach(b=>b.onclick=()=>memberForm(b.dataset.member));$$('[data-staff]').forEach(b=>b.onclick=()=>staffForm(b.dataset.staff));$$('[data-court]').forEach(b=>b.onclick=()=>courtForm(b.dataset.court));$$('[data-event]').forEach(b=>b.onclick=()=>eventDetail(b.dataset.event));$$('[data-payment]').forEach(b=>b.onclick=()=>deskPayment(b.dataset.payment));$$('[data-view]').forEach(b=>b.onclick=()=>{view=b.dataset.view;render();});const actions={'new-booking':()=>bookingForm(),'new-member':()=>memberForm(),'new-staff':()=>staffForm(),'new-event':eventForm,'new-expense':expenseForm,'new-court':()=>courtForm(),'new-club':clubForm,'prev-day':()=>{date=shiftDate(date,-1);render();},'next-day':()=>{date=shiftDate(date,1);render();},today:()=>{date=today();render();},logout:()=>setSession(null),menu:()=>{mobileOpen=!mobileOpen;$('.sidebar').classList.toggle('open',mobileOpen);},search:searchModal,alerts:()=>{showModal('Avvisi del circolo',attention());$('#modal').querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>{$('#modal').close();page=b.dataset.page;render();});},'export-cash':exportCash,backup:()=>exportFile('padel-backup-'+today()+'.json',JSON.stringify(state,null,2),'application/json'),'import-demo':importDemo};$$('[data-action]').forEach(b=>b.onclick=()=>actions[b.dataset.action]?.());if($('#agenda-date'))$('#agenda-date').onchange=e=>{if(e.target.value){date=e.target.value;render();}};if($('#member-filter'))$('#member-filter').oninput=e=>{filter=e.target.value;$('#member-table').innerHTML=memberTable();$$('[data-member]').forEach(b=>b.onclick=()=>memberForm(b.dataset.member));};if($('#admin-club'))$('#admin-club').onchange=e=>{session.clubId=e.target.value;try{sessionStorage.setItem('padel-demo-session',JSON.stringify(session));}catch{}date=today();render();};if($('#brand-form'))$('#brand-form').onsubmit=async e=>{e.preventDefault();const form=e.target,button=form.querySelector('button[type=submit]');button.disabled=true;try{const f=new FormData(form),c=club(),name=f.get('name').trim();if(!name)throw Error('Inserisci il nome del circolo.');const [logo,loginLogo]=await Promise.all([readLogo(f.get('logo')),readLogo(f.get('loginLogo'))]);Object.assign(c,{name,city:f.get('city').trim(),initials:f.get('initials').trim().slice(0,3)||'PC',primary:f.get('primary'),accent:f.get('accent'),canvas:f.get('canvas')});if(f.has('clearLogos'))c.logo=c.loginLogo='';else{if(logo)c.logo=logo;if(loginLogo)c.loginLogo=loginLogo;}const saved=persist();render();if(saved)toast('Identità del circolo aggiornata.');}catch(error){form.querySelector('.form-error').textContent=error.message;button.disabled=false;}};}
document.addEventListener('click',e=>{const btn=e.target.closest('[data-wallet],[data-sub]');if(btn?.dataset.wallet)wallet(btn.dataset.wallet);if(btn?.dataset.sub)substitutes(btn.dataset.sub);});
const paymentLabels={cash:'Contanti',pos:'POS',credit:'Credito interno',online:'Via internet',debt:'Insoluto',topup:'Ricarica'};
function deskPayment(value){
  const [id,index]=value.split('|'),b=bookings().find(x=>x.id===id),p=b?.players[index];
  if(!p)return;
  const m=account(state,b.clubId,p);
  if(p.paid){showModal('Quota registrata','<p>'+esc(p.name)+' · '+euro(p.amount)+' · '+esc(paymentLabels[p.deskMethod]||(p.method==='online'?'Via internet':'Al circolo'))+'</p>');return;}
  formModal('Quota di '+esc(p.name),'<p>'+euro(p.amount)+' · Credito disponibile '+euro((m.balance||0)/100)+'</p><label class="field"><span>Registra come</span><select name="method">'+Object.entries(paymentLabels).filter(([key])=>key!=='topup').map(([key,label])=>'<option value="'+key+'">'+label+'</option>').join('')+'</select></label>',f=>perform('payment',{bookingId:b.id,index:Number(index),method:f.get('method')}));
}
async function perform(op,p={}){
 if(revision===null){deskAction(state,club().id,op,p,false);persist();return}
 await pendingSave;const response=await fetch('/api/action/'+op,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({...p,clubId:club().id,revision})});
 const data=await response.json();if(!response.ok)throw Error(data.error||'Operazione rifiutata');state=data.state;revision=data.revision;
}
function shiftReport(){const shifts=(state.shifts||[]).filter(s=>s.clubId===club().id),active=shifts.find(s=>!s.closed);
 const report=shifts.slice().reverse().map(s=>'<p>'+esc(new Date(s.opened).toLocaleString('it-IT'))+' · '+(s.closed?'Chiuso':'Aperto')+' · '+['cash','pos','credit'].map(k=>paymentLabels[k]+' '+euro((state.ledger||[]).filter(t=>t.shiftId===s.id&&t.method===k).reduce((v,t)=>v+t.cents,0)/100)).join(' / ')+'</p>').join('');

  const tx=(state.ledger||[]).filter(t=>t.clubId===club().id&&t.date===date);
  return '<section class="panel panel-pad"><h2>Turni di cassa</h2>'+report+'<button class="button" data-shift="'+(active?'close':'open')+'">'+(active?'Chiudi turno':'Apri turno')+'</button></section><section class="panel panel-pad" style="margin-bottom:20px"><h2>Riepilogo giornaliero · '+esc(date)+'</h2><p class="section-note">Movimenti registrati al desk nella data selezionata.</p><div class="actions">'+['cash','pos','credit','online','debt','topup'].map(key=>'<p class="pill">'+paymentLabels[key]+' · '+euro(tx.filter(t=>t.method===key).reduce((s,t)=>s+t.cents,0)/100)+'</p>').join('')+'</div></section>';
}
document.addEventListener('click',async e=>{const op=e.target.closest('[data-shift]')?.dataset.shift;if(op)try{await perform(op);render()}catch(err){toast(err.message)}});
function wallet(id){
 const m=members().find(x=>x.id===id);
 formModal('Conto di '+esc(m.name),'<p>Credito '+euro((m.balance||0)/100)+' · Insoluti '+euro(outstandingDebt(state,id)/100)+'</p>'+field('Ricarica credito €','amount',0,'number')+field('Ora preferita (0–23)','hour',m.preferredHour??'','number')+'<label class="check"><input name="consent" type="checkbox" '+(m.whatsappConsent?'checked':'')+'>Consenso agli inviti WhatsApp</label>',async f=>{
 const cents=Math.round(Number(f.get('amount'))*100),hour=f.get('hour');
 if(!Number.isSafeInteger(cents)||cents<0||(hour!==''&&(!Number.isInteger(Number(hour))||Number(hour)>23)))throw Error('Controlla importo e orario.');
 if(cents)await perform('topup',{memberId:id,cents});const current=members().find(x=>x.id===id);current.whatsappConsent=f.has('consent');current.preferredHour=hour===''?null:Number(hour);
 });
}
function substitutes(id){
 const b=bookings().find(x=>x.id===id);if(!b||b.players.length>=4)return;
 const searches=state.searches||=[],existing=searches.find(s=>s.bookingId===id&&s.clubId===club().id);
 if(existing){showModal('Ricerca sostituto',existing.winner?'<p>'+esc(members().find(m=>m.id===existing.winner)?.name)+' ha accettato. Il desk può inserirlo manualmente su Playtomic.</p>':liveWhatsApp?'<p>Inviti WhatsApp</p>'+existing.ids.map(mid=>esc(members().find(m=>m.id===mid)?.name)+' · '+esc(existing.delivery?.[mid]||'In attesa')+'<br>').join(''):'<p>Inviti simulati · risposte disponibili</p>'+existing.ids.map(mid=>'<button class="button secondary" data-accept="'+mid+'">'+esc(members().find(m=>m.id===mid)?.name)+' · PRENOTO</button>').join(''));$$('[data-accept]').forEach(btn=>btn.onclick=async()=>{if(existing.winner)return;try{await perform('reply',{bookingId:id,memberId:btn.dataset.accept})}catch(e){toast(e.message);return;}$("#modal").close();render();toast('Ricerca chiusa. Inserisci il giocatore su Playtomic.');});return;}
 formModal('Trova sostituto · '+esc(b.start),field('Livello minimo','min',3,'number')+field('Livello massimo','max',4.5,'number')+'<p class="section-note">Usa livello e ora preferita o storica dei soci del circolo. '+(liveWhatsApp?'Gli inviti raggiungono i soci con consenso WhatsApp.':'Inviti simulati nella demo.')+'</p>',f=>perform('search',{bookingId:id,min:Number(f.get('min')),max:Number(f.get('max'))}));
}
function debtBadge(b,p){const m=members().find(x=>p.memberId?x.id===p.memberId:p.externalId?x.externalId===p.externalId:x.name===p.name);const due=m&&outstandingDebt(state,m.id);return due?'<strong style="color:#ad302e"> · Insoluti '+euro(due/100)+'</strong>':'';}

